export const ALL_ALPHABET = ["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O","P","R","S","T","U","V","W","X","Y","Z"];

export function getNamesByLetter(letter) {
  return nepaliNames.filter(n => n.name.charAt(0).toUpperCase() === letter.toUpperCase());
}

export function getNamesByGender(gender) {
  return nepaliNames.filter(n => n.gender === gender);
}

export function getNamesByCategory(category) {
  return nepaliNames.filter(n => n.categories.includes(category));
}

export function getNameBySlug(slug) {
  return nepaliNames.find(n => n.slug === slug);
}

export function getNamesByLetterAndGender(letter, gender) {
  return nepaliNames.filter(n => n.name.charAt(0).toUpperCase() === letter.toUpperCase() && n.gender === gender);
}

export function searchNames(query) {
  const q = query.toLowerCase();
  return nepaliNames.filter(n => n.name.toLowerCase().includes(q) || n.meaning.toLowerCase().includes(q) || n.nepaliName.includes(query) || n.meaningKeywords.some(k => k.includes(q)));
}

export function getLetterCounts(names, gender) {
  const c = {};
  for (const l of ALL_ALPHABET) c[l] = 0;
  const pool = names || nepaliNames;
  const filtered = (gender && gender !== 'All') ? pool.filter(n => n.gender === gender) : pool;
  for (const n of filtered) {
    const l = n.name.charAt(0).toUpperCase();
    if (c[l] !== undefined) c[l]++;
  }
  return c;
}

export function getNamesPaginated(names, page, perPage) {
  const total = names.length;
  const totalPages = Math.max(1, Math.ceil(total / perPage));
  const start = (Math.max(1, Math.min(page, totalPages)) - 1) * perPage;
  return { names: names.slice(start, start + perPage), total, totalPages };
}

export function getGenderCounts(names) {
  const pool = names || nepaliNames;
  const counts = {};
  for (const n of pool) {
    counts[n.gender] = (counts[n.gender] || 0) + 1;
  }
  counts.Unisex = counts.Unisex || 0;
  return counts;
}
